<script setup lang="ts">
import AdvancedPage from '../../app/AdvancedPage.vue'
import { number, percent } from '../../format'
import StatusBadge from '../../components/StatusBadge.vue'
import { computed,ref,defineAsyncComponent } from 'vue'
import { useExperimentStore } from '../../stores'
import type { ChartResponse } from '../../types'
import { api } from '../../api'
import ExperimentComparisonChart from '../../components/ExperimentComparisonChart.vue'
import KronosEvaluation from '../../components/KronosEvaluation.vue'
const EquityChart=defineAsyncComponent(()=>import('../../components/EquityChart.vue'))
const experiments=useExperimentStore();const comparisonMetric=ref('netPnl');const exportError=ref('')
const metricChart = computed<ChartResponse>(() => ({ title: 'Comparación de métricas disponibles', unit: comparisonMetric.value === 'winRate' || comparisonMetric.value === 'returnOnCapital' ? 'fracción' : 'USD / ratio', series: experiments.experiments.map(e => { const m = e.metrics; const keys: Record<string, number | null | undefined> = { netPnl: m?.netPnl, profitFactor: m?.profitFactor, maximumDrawdown: m?.maximumDrawdown, expectancy: m?.expectancy, winRate: m?.winRate, fees: m?.fees, returnOnCapital: m?.returnOnCapital }; const v = keys[comparisonMetric.value]; return { name: e.id, points: v == null || !e.startedAt ? [] : [{ at: e.startedAt, value: v }] } }) }))
const calibrationChart = computed<ChartResponse>(() => ({ title: 'Probabilidad prevista frente a TP observado', unit: 'probabilidad', series: [{ name: 'Buckets con evidencia', points: (experiments.calibration?.buckets ?? []).filter(b => b.average_probability != null && b.observed_tp_rate != null).map(b => ({ at: String(b.average_probability), value: b.observed_tp_rate! })) }] }))
async function download() { try { const data = await api.snapshot(); const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = `tradingagent-${new Date().toISOString().replaceAll(':', '-')}.json`; a.click(); URL.revokeObjectURL(url) } catch { exportError.value = 'No se pudo exportar: DATA_UNAVAILABLE.' } }

</script>
<template><AdvancedPage title="Reportes y calibración" description="Comparación económica sin seleccionar por acierto solamente."><template #action><button class="secondary-button" @click="download">Exportar evidencia</button></template><p v-if="exportError" class="error-banner">{{ exportError }}</p><ExperimentComparisonChart :experiments="experiments.experiments" /><section class="card"><div class="panel-heading"><h3>Comparación económica</h3><select v-model="comparisonMetric" aria-label="Métrica comparativa"><option value="netPnl">P&L neto</option><option value="profitFactor">Profit factor</option><option value="maximumDrawdown">Drawdown máximo</option><option value="expectancy">Expectativa</option><option value="winRate">Win rate</option><option value="fees">Comisiones</option><option value="returnOnCapital">Retorno sobre capital</option></select></div><EquityChart :chart="metricChart" kind="bar" /></section><section class="card"><div class="panel-heading"><h3>Calibración de probabilidad</h3><StatusBadge :value="experiments.calibration?.status ?? 'INSUFFICIENT_EVIDENCE'" /></div><p class="muted">Probabilidad del motor empírico, no confianza subjetiva de Sol. Brier: {{ number(experiments.calibration?.brier_score, 4) }}</p><EquityChart :chart="calibrationChart" probability-axis kind="scatter" :height="230" /><div class="table-scroll"><table><thead><tr><th>Bucket</th><th>Predicción media</th><th>TP observado</th><th>Muestra</th><th>Diferencia</th></tr></thead><tbody><tr v-for="b in experiments.calibration?.buckets" :key="b.bucket"><td>{{ b.bucket }}</td><td>{{ percent(b.average_probability) }}</td><td>{{ percent(b.observed_tp_rate) }}</td><td>{{ b.samples }}</td><td>{{ b.average_probability != null && b.observed_tp_rate != null ? percent(b.average_probability - b.observed_tp_rate) : 'No evaluable' }}</td></tr></tbody></table></div></section><KronosEvaluation /></AdvancedPage></template>
